#!/usr/bin/env node
/** Build a transactional SQL Editor bundle without contacting Supabase. */
import { createHash } from 'node:crypto';
import { readFile, readdir, writeFile } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { buildImport } from './import-catalog.mjs';
const root=resolve(dirname(fileURLToPath(import.meta.url)),'..');
const quote=value=>`'${value.replaceAll("'","''")}'`;
export async function buildBundle() {
 const files=(await readdir(resolve(root,'supabase/migrations'))).filter(f=>/^\d+_.+\.sql$/.test(f)).sort();
 const parts=[`-- Generated by scripts/build-supabase-bundle.mjs. Review before applying.\n-- Single transaction; re-running this exact bundle skips applied schema versions.\nBEGIN;\nSELECT pg_advisory_xact_lock(hashtext('gcet-schema-bundle'));\nCREATE SCHEMA IF NOT EXISTS supabase_migrations;\nCREATE TABLE IF NOT EXISTS supabase_migrations.schema_migrations (version text NOT NULL PRIMARY KEY, statements text[], name text);\nALTER TABLE supabase_migrations.schema_migrations ADD COLUMN IF NOT EXISTS statements text[];\nALTER TABLE supabase_migrations.schema_migrations ADD COLUMN IF NOT EXISTS name text;\nCREATE TABLE IF NOT EXISTS supabase_migrations.gcet_bundle_checksums (version text PRIMARY KEY REFERENCES supabase_migrations.schema_migrations(version) ON DELETE CASCADE, sha256 text NOT NULL);\nREVOKE ALL ON SCHEMA supabase_migrations FROM anon, authenticated;\nREVOKE ALL ON TABLE supabase_migrations.schema_migrations,supabase_migrations.gcet_bundle_checksums FROM anon,authenticated;\n`];
 const versions=[];
 for(const file of files) {
  const [,version,name]=/^(\d+)_(.+)\.sql$/.exec(file);
  const sql=await readFile(resolve(root,'supabase/migrations',file),'utf8');
  const hash=createHash('sha256').update(sql).digest('hex');
  const tag=`$gcet_source_${hash.slice(0,16)}$`;
  if(sql.includes(tag)) throw new Error('Unexpected dollar quote collision');
  versions.push({version,name,sha256:hash});
  parts.push(`DO $gcet_apply_${version}$\nDECLARE migration_sql text := ${tag}${sql}${tag}; stored_hash text;\nBEGIN\n IF EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version=${quote(version)}) THEN\n  SELECT sha256 INTO stored_hash FROM supabase_migrations.gcet_bundle_checksums WHERE version=${quote(version)};\n  IF stored_hash IS NULL THEN\n   RAISE EXCEPTION 'Version ${version} exists without a GCET checksum. Verify original CLI migration history before applying this bundle; no changes applied.';\n  ELSIF stored_hash <> ${quote(hash)} THEN\n   RAISE EXCEPTION 'Version ${version} checksum changed. Create a new migration instead of changing applied SQL; no changes applied.';\n  END IF;\n ELSE\n  EXECUTE migration_sql;\n  INSERT INTO supabase_migrations.schema_migrations(version,statements,name) VALUES (${quote(version)},ARRAY[migration_sql],${quote(name)});\n  INSERT INTO supabase_migrations.gcet_bundle_checksums(version,sha256) VALUES (${quote(version)},${quote(hash)});\n END IF;\nEND;\n$gcet_apply_${version}$;\n`);
 }
 const imported=await buildImport();
 parts.push(imported.sql.replace(/^BEGIN;\n/m,'').replace(/\nCOMMIT;\n$/,'\n'));
 parts.push(`COMMIT;\n-- Owner verification, after commit:\nSELECT version,name FROM supabase_migrations.schema_migrations ORDER BY version;\nSELECT 'subjects' AS entity,count(*) AS rows FROM public.subjects UNION ALL SELECT 'resources',count(*) FROM public.resources UNION ALL SELECT 'quarantined_groups',count(*) FROM public.import_quarantine;\n`);
 return {sql:parts.join('\n'),versions,report:imported.report};
}
if(process.argv[1]&&resolve(process.argv[1])===fileURLToPath(import.meta.url)) {
 const {sql,versions}=await buildBundle();
 await writeFile(resolve(root,'supabase/deploy.sql'),sql);
 await writeFile(resolve(root,'supabase/deploy.manifest.json'),JSON.stringify(versions,null,2)+'\n');
 console.log(`Generated supabase/deploy.sql: ${versions.length} guarded migrations plus insert-only catalog (${Buffer.byteLength(sql)} bytes).`);
}
